SELECT jsonb_build_object('observedAt',clock_timestamp(),'readOnly',current_setting('transaction_read_only'),'pieces',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.building_id::text,i.owner_entity_id::text,i.instance_id,i.building_type,i.transform)),'[]') FROM dune.building_instances i),'placeables',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id::text,'owner',p.owner_entity_id::text,'type',p.building_type,'location',to_jsonb((a.transform).location),'rotation',to_jsonb((a.transform).rotation))),'[]') FROM dune.placeables p JOIN dune.actors a ON a.id=p.id WHERE NOT p.is_hologram),'totems',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id::text,'entity',af.entity_id::text,'claimCells',(SELECT count(*) FROM dune.landclaim_segments ls WHERE ls.totem_id=a.id),'name',pa.actor_name,'map',a.map,'location',to_jsonb((a.transform).location))),'[]') FROM dune.actors a JOIN dune.totems t ON t.id=a.id LEFT JOIN dune.permission_actor pa ON pa.actor_id=a.id LEFT JOIN dune.actor_fgl_entities af ON af.actor_id=a.id WHERE a.state IS DISTINCT FROM 'BaseBackup'))::text;
